def diagram(name,title,boxes,lines,notes):
    s='<svg xmlns="http://www.w3.org/2000/svg" width="960" height="540" viewBox="0 0 960 540"><rect width="960" height="540" fill="#f1f6fa"/><g font-family="Arial,sans-serif" fill="#183247"><text x="35" y="42" font-size="25" font-weight="bold">'+html.escape(title)+'</text>'
    for x1,y1,x2,y2,label in lines:
        s+=f'<path d="M{x1} {y1} L{x2} {y2}" stroke="#df9432" stroke-width="4" fill="none"/><circle cx="{x2}" cy="{y2}" r="6" fill="#df9432"/><text x="{(x1+x2)/2}" y="{(y1+y2)/2-10}" text-anchor="middle" font-size="17">{html.escape(label)}</text>'
    for x,y,w,h,heading,rows in boxes:
        s+=f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="12" fill="white" stroke="#26778b" stroke-width="2"/><text x="{x+16}" y="{y+30}" font-size="22" font-weight="bold">{html.escape(heading)}</text>'
        for i,row in enumerate(rows):s+=f'<text x="{x+16}" y="{y+60+i*27}" font-size="19">{html.escape(row)}</text>'
    for i,n in enumerate(notes):s+=f'<text x="35" y="{478+i*26}" font-size="18">{html.escape(n)}</text>'
    s+='</g></svg>'
    p=ROOT/(name+'.svg');p.write_text(s,encoding='utf-8');assets.append(p)
    return photo(URL+p.name,title)
arch=diagram('architecture','Програма и данни в обща памет',[(300,75,370,145,'ПАМЕТ',['Инструкции: зареди, събери, запиши','Данни: 7, 5, …','Резултат: 12']),(300,310,370,120,'ПРОЦЕСОР',['Управление + АЛУ + регистри']),(25,310,200,120,'ВХОД',['Клавиатура','Въвеждаш: 7 и 5']),(750,310,190,120,'ИЗХОД',['Екран','Виждаш: 12'])],[(480,220,480,310,'извличане / запис'),(225,365,300,365,''),(670,365,750,365,'')],['Линиите показват обмен, а не физическото разположение на частите.','Същата система изпълнява друга задача, когато заредим друга програма.'])
