bits=diagram('bits','Един байт: осем позиции, две възможности във всяка',[(35,90,890,100,'0     0     0     0     0     1     0     1',['Двоичният запис 00000101 представя числото 5.']),(35,270,410,145,'Капацитет',['Колко данни се побират?','Пример: 8 GB или 16 GB RAM']),(500,270,425,145,'Скорост на пренос',['Колко данни се пренасят за време?','Пример: GB/s'])],[],['8 бита = 1 байт. Осем бита дават 256 различни комбинации.','Повече място не означава автоматично по-бърз достъп.'])
