def info(id,title,body):steps.append({'id':id,'step_content':{'type':'information','title':title,'instruction':wrap(body),'instruction_format':'html'},'step_rules':{}})
def choice(id,question,opts,correct,feedback):
    assert len(opts)==6
    steps.append({'id':id,'step_content':{'type':'multiple_choice','title':'Провери разбирането си','instruction':wrap('<p>'+question+'</p><p><strong>Избери всички верни отговори.</strong></p>'),'instruction_format':'html','options':[{'id':str(i+1),'text':v} for i,v in enumerate(opts)],'correct_option_ids':[str(i+1) for i in correct],'feedback':feedback},'step_rules':{'automatic_feedback':True}})
def opened(id,title,question,answer,ai=False):steps.append({'id':id,'step_content':{'type':'open_answer','title':title,'instruction':wrap('<p>'+question+'</p>'),'instruction_format':'html','reference_answer':answer},'step_rules':{'ai_feedback':ai,'automatic_feedback':not ai}})

info('intro','За какво е този урок?',photo('https://images.unsplash.com/photo-1636489953081-c4ebbd50fa3a?auto=format&fit=crop&w=1200&q=85','Геймърски компютър с монитор, клавиатура и мишка.')+'''<p>Урокът е за <strong>това как е устроен съвременният компютър, как работят заедно основните му части и как се е стигнало до тази организация</strong>.</p><ul><li><strong>Как една машина изпълнява различни задачи</strong> — значението на архитектурата на Фон Нойман и съхраняваната програма.</li><li><strong>Как процесорът и паметта работят заедно</strong> — изпълнение на инструкции, обработка и съхраняване на данни.</li><li><strong>Какво означават основните характеристики на компютъра</strong> и как компонентите образуват подходяща конфигурация.</li><li><strong>Как компютрите се развиват през поколенията</strong>, включително развитието на компютърната техника в България.</li></ul>''')
info('architecture-importance','Защо архитектурата на Фон Нойман е важна', '''<p>Представи си, че за да преминеш от една задача към друга, не е достатъчно да отвориш друга програма. Трябва да пренаредиш кабели и да настроиш превключватели. Така първоначално се подготвя за нови задачи една от ранните електронни изчислителни машини — ENIAC. Подготовката изисква време и внимателна работа.</p><p>Преди и по времето на Фон Нойман съществуват различни начини за организиране и управление на изчислителните машини. Някои получават инструкции от перфолента, а други се настройват чрез кабелни връзки и превключватели. Изследователите търсят начин една машина по-лесно да преминава към различни задачи.</p>'''+photo(ENIAC,'ENIAC: операторите работят пред панели с кабели и превключватели. Първоначалното задаване на задачите се различава от зареждането на програма днес. U. S. Army Photo.')+'''<p>Решаващата идея е <strong>самата програма да се съхранява в паметта</strong>. В описаната от Фон Нойман организация паметта съдържа и инструкции, и данни. Процесорът извлича инструкциите и ги изпълнява. За нова задача зареждаме друга програма, вместо да променяме физическите връзки на машината.</p><p>Докладът на Фон Нойман от 1945 г. помага тези идеи, разработвани заедно с други изследователи, да се разпространят. Организацията става известна като <strong>архитектура на Фон Нойман</strong> и оказва огромно влияние върху развитието на компютрите.</p><p>Масово съвременните компютри използват принципите на тази архитектура. Затова на един и същ компютър можеш първо да пресмяташ в електронна таблица, после да рисуваш, а след това да слушаш музика. <strong>Сменяш програмата, а компютърът остава същият.</strong></p>''')
info('architecture','Архитектура на Фон Нойман', '''<p>Представи си, че първо използваш компютъра като калкулатор, а след това отваряш програма за рисуване. Не сменяш електронните му части и не свързваш отново кабелите. Зареждаш друга <strong>програма</strong> — друга последователност от инструкции. Именно възможността машината да пази и изпълнява програма е ключ към нейната универсалност.</p><p>През 1945 г. Джон фон Нойман описва в доклад за EDVAC организация на електронна изчислителна машина, развита в работата на изследователски екип. Тази организация става известна като <strong>архитектура на Фон Нойман</strong>. „Архитектура“ тук означава основните части на системата, техните роли и връзките между тях.</p>'''+arch+'''<p>Разгледай паметта в схемата: в нея има <strong>и инструкции, и данни</strong>. Процесорът извлича инструкция, разбира какво действие е зададено и го изпълнява с необходимите данни. Входните устройства подават информация, а изходните представят резултатите. За събиране данните могат да бъдат 7 и 5; при рисуване — координати и цветове.</p><p>Основните принципи включват електронно изпълнение на операциите, двоично представяне на информацията с 0 и 1 и управление чрез съхранявана в паметта програма. Съвременните системи развиват тези идеи с няколко ядра и сложна организация на паметта. Не е необходимо всяка реална машина да изглежда точно като опростената схема.</p>''')
choice('architecture-check','Същият компютър първо обработва числа, а после рисунка. Кои обяснения са верни?',['Зареждането на друга програма променя изпълняваните инструкции.','За всяка нова задача задължително се сменя процесорът.','В модела на Фон Нойман общата памет съдържа инструкции и данни.','Двоично се представят само числата, но не и инструкциите.','Входът подава данни, а изходът представя резултатите.','Архитектурата описва само външния вид на корпуса.'],[0,2,4],'Програмата задава действията на същия хардуер. В модела паметта съдържа и инструкции, и данни; архитектурата описва организацията на системата.')
info('cpu','Централен процесор: кой какво прави?',photo('https://upload.wikimedia.org/wikipedia/commons/a/a5/AMD_Athlon_X2_BE-2300_ADH2300IAA5DO_top.png','Процесор AMD Athlon X2. Под металния капак се намира чипът с изчислителните и управляващите блокове.',credit('Hundehalter','AMD_Athlon_X2_BE-2300_ADH2300IAA5DO_top.png','3.0'))+'''<p>Когато калкулаторът покаже 12 след 7 + 5, това изглежда като едно действие. Вътре обаче различни части на <strong>централния процесор — CPU</strong> изпълняват различни роли. Процесорът изпълнява инструкциите на програмата и участва в координирането на работата на системата.</p><p><strong>Аритметично-логическото устройство — АЛУ</strong> извършва операции като събиране, изваждане и сравнение. Сравнението също е важно: например програмата трябва да установи дали наличната сума е достатъчна за покупка. Не всяка операция непременно се извършва от един и същ вътрешен блок при реалните процесори.</p><p><strong>Управляващото устройство</strong> разчита инструкциите и подава сигналите, които организират изпълнението им. То не събира числата вместо АЛУ, но определя кога и с кои данни трябва да се извърши действието. <strong>Регистрите</strong> са много малки и бързи места за временно съхранение вътре в процесора. В тях могат да стоят числата за текущата операция, резултатът или адресът на следваща инструкция.</p><p>Тези роли си сътрудничат. Ако сравним работата с пресмятане на лист, инструкцията казва какво да направим, числата са подръка, а резултатът се записва за следващото действие. Аналогията помага за ролите, но процесорът работи с електронни сигнали, а не разбира задачата като човек.</p>''')
choice('cpu-check','Програмата сравнява цена и налична сума. Кои роли са описани правилно?',['АЛУ може да извърши сравнение.','Регистрите пазят всички лични файлове постоянно.','Управляващото устройство координира действията чрез сигнали.','CPU е друго име на целия компютърен корпус.','Регистрите могат да държат стойности за текущата операция.','Управляващото устройство заменя RAM и SSD.'],[0,2,4],'АЛУ обработва операции, управлението организира изпълнението, а регистрите пазят малки количества временни данни в CPU.')
info('buses','Шини: как частите обменят информация?',arch+'''<p>Процесорът не може да използва данните в паметта, ако няма начин да ги получи. Електронните връзки, по които компонентите обменят информация, се наричат <strong>шини</strong>. На схемата линиите показват обмена; в действителния компютър той се осъществява чрез електрически връзки и съответните контролери.</p><p>Представи си, че трябва да прочетеш стойност от определено място в паметта. Системата трябва да уточни <strong>къде</strong> е стойността, <strong>какво действие</strong> се иска и <strong>какви данни</strong> се пренасят. Затова различаваме адресна шина, управляващи сигнали и шина за данни. Адресът посочва място; той не е самата стойност в това място.</p><p>Ширината на шината за данни показва колко бита могат да се пренесат едновременно по нея. При опростен пример за 64 бита по 32-битова шина са нужни две порции, а по 64-битова — една. Това сравнение има смисъл само при еднакви останали условия. Скоростта зависи и от честотата, организацията и забавянията.</p><p>Изразът „64-битов процесор“ не означава, че всяка връзка в компютъра е точно 64-битова. Регистри, адресиране и различни интерфейси имат собствени характеристики. По-широка шина сама по себе си не доказва, че целият компютър е по-бърз.</p>''')
choice('buses-check','Трябва да прочетем стойността от място с адрес 100. Кои твърдения са верни?',['Адресът посочва откъде да бъде прочетена стойността.','Данните задължително са числото 100.','Управляващ сигнал указва операцията четене.','Шината за данни пренася прочетената стойност.','64-битов процесор означава, че всяка негова връзка е 64-битова.','Двойно по-широка шина винаги прави целия компютър двойно по-бърз.'],[0,2,3],'Адресът е място, данните са съдържание, а управлението указва действието. Производителността зависи и от други характеристики.')
info('cycle','От инструкцията до резултата', '''<p>Програмата е подготвила две стойности: 7 и 5. За да получи 12, процесорът трябва да изпълни инструкция за събиране. Ще проследим опростен пример, в който стойностите вече са заредени в два регистъра. Имената R1, R2 и R3 са условни, за да виждаме ясно къде стоят данните.</p>'''+cycle+'''<p>Първо процесорът <strong>извлича инструкцията</strong> от паметта. Управляващото устройство я разчита: каква операция трябва да се изпълни, кои данни участват и къде се очаква резултатът. След това АЛУ събира стойностите от R1 и R2, а полученото 12 се записва в R3.</p><p>Следваща инструкция може да използва 12 в ново изчисление или да го запише в оперативната памет. Друга част от програмата организира показването му на екрана. Самото събиране не означава автоматично, че числото вече е изобразено.</p><p>Тази повтаряща се последователност се нарича <strong>цикъл на изпълнение на инструкция</strong>. В учебния модел виждаме извличане, разчитане, получаване на нужните данни, изпълнение и записване. В действителните процесори някои дейности се припокриват и не всяка инструкция чете RAM или използва АЛУ по един и същ начин. Основната идея остава: резултатите възникват чрез изпълнение на конкретни инструкции.</p>''')
opened('cycle-check','Разкажи пътя на едно изчисление','Обясни със свои думи как процесорът получава резултат от събиране. Дай собствен пример с две числа и посочи ролята на управлението, АЛУ и регистрите.','Например 9 + 4: процесорът извлича и разчита инструкцията. Стойностите 9 и 4 са подготвени в регистри. Управляващото устройство организира действието, АЛУ получава 13, а резултатът се записва в регистър. Следваща инструкция може да го използва или да го запише в RAM.')
info('cpu-spec','Какво означават характеристиките на процесора?',photo(CPU,'На корпуса се виждат моделът и честота 3,40 GHz. За оценка са нужни и други характеристики.',cpucredit)+'''<p>В обява за компютър често първо се забелязва числото до GHz. То изглежда като лесен начин да изберем „по-бързия“ процесор. Но една цифра не описва цялата му работа. Трябва да знаем точния модел, архитектурата и за каква задача ще го използваме.</p><p><strong>Тактовата честота</strong> описва броя тактове за секунда. Един MHz е един милион такта, а един GHz — един милиард. При 3 GHz имаме три милиарда такта в секунда, но не непременно три милиарда завършени инструкции. Една инструкция може да изисква повече тактове, а процесорът може да обработва части от няколко инструкции едновременно.</p><p><strong>Разрядността</strong> описва ширината в битове на основните регистри и обработваните от архитектурата цели стойности. При 64-битова архитектура това са 64 бита. Тя не означава 64 ядра и сама по себе си не доказва двойна скорост спрямо 32-битова система.</p><p><strong>Ядрата</strong> позволяват работа по повече изпълнителни потоци, когато програмите могат да я разпределят. <strong>Кешпаметта</strong> намалява част от чакането за данни. Значение имат също размерът и типът на кеша, поддържаните инструкции и възможностите за обработка и пренасяне на данни.</p><p>Затова два различни модела с еднаква честота може да имат различна производителност. А програма, която използва главно едно ядро, няма непременно да стане два пъти по-бърза при удвояване на ядрата. Сравняваме резултати за сходни задачи, а не само най-голямото число в рекламата.</p>''')
choice('cpu-spec-check','Два различни модела процесори работят на 3 GHz. Какво можем да заключим?',['Посочената честота е еднаква.','Те винаги изпълняват еднакъв брой инструкции за секунда.','Архитектурата и кешът могат да повлияят на резултата.','Повече ядра ускоряват всяка програма точно пропорционално.','За избор е полезно сравнение при задачите, които ще изпълняваме.','3 GHz означава 3 GB оперативна памет.'],[0,2,4],'Честотата измерва тактове, а не обем или гарантиран брой инструкции. Архитектурата, кешът, ядрата и програмата също влияят.')
info('ram','Оперативна памет: работното място на програмите',photo(RAM,'RAM модул: платката носи чипове памет; контактите по долния ръб го свързват с дънната платка.',ramcredit)+'''<p>Отваряш презентация, добавяш снимка и пренареждаш слайдовете. Компютърът трябва непрекъснато да има подръка програмата и данните за текущата работа. Тази роля изпълнява <strong>оперативната памет</strong>, обикновено RAM — памет с произволен достъп. „Произволен“ означава, че може да се достигне избрано адресируемо място, без да се прочете последователно всичко преди него.</p><p>На снимката виждаш модул с няколко чипа. В настолния компютър такива модули се поставят в специални слотове. В някои мобилни устройства паметта е запоена. Това е физическото устройство, което осигурява пространство за текущите програми и данни.</p><p>Обичайната RAM е <strong>енергозависима</strong>: съдържанието ѝ се губи при прекъсване на захранването. Затова редактирането и записването не са едно и също. Докато променяш слайдовете, работното състояние се поддържа в RAM; когато запишеш файла, промените се съхраняват на SSD, твърд диск или друго трайно хранилище.</p><p>Ако отворените програми изискват повече памет, отколкото има, системата може да използва устройството за съхранение като помощ. Това обикновено е по-бавно. Допълнителната RAM може да помогне в тази ситуация, но не ускорява непременно всяка малка задача.</p>''')
choice('ram-check','Редактираш презентация, но още не си записал последните промени. Кои твърдения са верни?',['RAM участва в текущата работа на програмата.','Промените задължително са вече във файла на SSD.','При спиране на захранването незаписаната работа може да се изгуби.','Повече RAM винаги удвоява скоростта на презентацията.','Записването съхранява промените в траен файл.','Произволният достъп означава, че компютърът избира данните на късмет.'],[0,2,4],'RAM държи текущото състояние. Записването е отделно действие към трайното хранилище; автоматичното записване помага само ако действително е извършено.')
info('cache','Защо процесорът използва кеш?',memory+'''<p>Процесорът може да обработва данни много бързо, но често трябва да чака да ги получи. Представи си редактор, който многократно обработва едни и същи части от документ. Ако всеки път чака достъп до по-бавна памет, част от времето се губи в обмен вместо в работа.</p><p><strong>Кешпаметта</strong> пази близо до процесорните ядра копия на инструкции и данни, които вероятно ще потрябват скоро. Когато търсеното е там, достъпът е по-бърз. Когато го няма, информацията се получава от следващо ниво на паметта. Кешът не е място, в което ръчно подреждаме документите си, и не заменя RAM.</p><p>В схемата проследи различните роли. SSD пази записания файл. При отваряне необходимите данни попадат в RAM. CPU изпълнява редактора, като използва регистри и кеш за непосредствената обработка. След редакция командата „Запиши“ обновява трайния файл.</p><p>Можем да сравним организацията с работа на бюро: материалите подръка спестяват разходки до шкафа. Но това е само аналогия за близостта и бързия достъп. В компютъра копията и обменът се управляват автоматично. Важното е, че <strong>различните видове памет съчетават различен капацитет, скорост и цена</strong>, вместо една памет да е най-добра във всичко.</p>''')
opened('memory-ai','Обясни какво се случва с документа','Създаваш доклад, записваш го, добавяш още един абзац и токът спира преди следващото записване. Обясни със свои думи ролите на SSD, RAM, кеша и процесора. Коя версия очакваш да намериш след включване, ако няма автоматично записване? Дай собствен пример за съдържанието на доклада.','Например пиша доклад за слънчевата енергия. SSD пази последната записана версия. Редакторът използва RAM за текущото състояние, а процесорът изпълнява инструкциите с помощта на регистри и кеш за бърз достъп. След спирането незаписаният абзац може да се изгуби. Очаквам последната записана версия без новия абзац, ако не е имало автоматично записване.',True)
info('memory-spec','Битове, байтове и характеристики на паметта',bits+'''<p>Електронната памет представя информацията чрез състояния, които означаваме с 0 и 1. Една такава двоична единица е <strong>бит</strong>. Осем бита образуват <strong>байт</strong>. Това не означава, че всяка буква винаги заема точно един байт: броят зависи от използваното кодиране.</p><p>В илюстрацията един байт съдържа 00000101. В този числов пример това е 5. Осемте позиции могат да образуват 256 различни комбинации. Компютърът използва последователности от байтове, за да представя текстове, изображения, инструкции и други данни.</p><p><strong>Капацитетът</strong> показва колко информация се побира. В десетичните означения 1 kB е 1000 байта, 1 MB е един милион, а 1 GB — един милиард байта. За двоични количества се използват KiB, MiB и GiB: 1 KiB е 1024 байта. В интерфейси и обяви означенията невинаги са последователни, затова проверяваме единицата.</p><p><strong>Закъснението при достъп</strong> показва колко време чакаме за данните, а <strong>скоростта на пренос</strong> — колко данни могат да се пренесат за секунда. Честотата е свързана с работата на паметта, но не е същото като време за достъп. Памет с по-голям капацитет не е автоматично по-бърза: по-големият шкаф побира повече, но това само по себе си не прави вземането на папка по-бързо.</p>''')
choice('memory-spec-check','Как правилно да разчетем характеристиките?',['16 байта съдържат 128 бита.','Капацитетът показва времето за прочитане на една стойност.','GB/s описва количество данни за секунда.','Всяка кирилска буква винаги е точно един байт.','По-голям капацитет и по-бърз достъп са различни предимства.','1 GHz е единица за обем памет.'],[0,2,4],'16 × 8 = 128 бита. GB/s е скорост на пренос; капацитетът е количество, а закъснението е време.')
info('gen-early','Поколения компютри: от релето до електронната лампа',photo(ENIAC,'ENIAC: сравни размерите на шкафовете с хората до тях. U. S. Army Photo.')+'''<p>За да разберем защо днешният компютър се побира на бюро, трябва да погледнем елементите, от които е изграден. В учебната класификация поколенията се различават преди всичко по своята <strong>елементна база</strong>, а не по външния вид или годината на покупка.</p><p>Към нулевото поколение се отнасят електромеханичните машини с <strong>релета</strong>. Релето превключва чрез движение на контакт, управлявано от електромагнит. Механичното движение ограничава скоростта и износва частите. Електронната лампа позволява управление на електрическия поток без такова движение.</p><p>Първото електронно поколение използва <strong>електронновакуумни лампи</strong>. На снимката се вижда колко пространство може да заема подобна система. Хиляди лампи изискват захранване, отделят топлина и правят охлаждането и поддръжката важна част от работата. Данните се въвеждат с устройства като четци на перфокарти; използват се и магнитни носители. Работата обикновено е организирана около една задача, а не около познатия днес работен плот с много отворени приложения.</p><p>Учебникът посочва 1949–1958 г. за първо поколение; по-ранни лампови машини като ENIAC показват, че историческите граници са приблизителни. Посочените скорости от десетки до стотици хиляди операции в секунда са ориентировъчни за различни машини и операции, а не характеристика, еднаква за цялото поколение.</p>''')
choice('gen-early-check','Какво обяснява големите размери и трудната поддръжка на ранните електронни компютри?',['Използването на множество електронни лампи.','Необходимостта от захранване и отвеждане на топлината.','Наличието на съвременен графичен работен плот.','Еднаквите характеристики на всички машини от периода.','Елементната база е важна за размерите и надеждността.','Всяка машина с голям монитор е от първо поколение.'],[0,1,4],'Лампите, захранването и охлаждането обясняват голяма част от размерите и поддръжката. Поколението се определя от технологиите, не от монитора.')
info('gen-transistor','Транзистори и интегрални схеми','''<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px;margin:20px 0"><figure style="margin:0"><h3>Електронна лампа</h3><img src="https://upload.wikimedia.org/wikipedia/commons/8/8b/ECC83.jpg" alt="Три електронни лампи ECC83 със стъклени корпуси" style="height:200px;width:100%;object-fit:contain"><figcaption>В стъкления корпус се виждат електродите. На снимката: примери за лампи ECC83.</figcaption></figure><figure style="margin:0"><h3>Транзистор</h3><img src="https://upload.wikimedia.org/wikipedia/commons/d/d4/Generic_2N2222A.jpeg" alt="Транзистор 2N2222A с три извода" style="height:200px;width:100%;object-fit:contain"><figcaption>Отделен полупроводников елемент. Този транзистор има три извода за свързване.</figcaption></figure><figure style="margin:0"><h3>Интегрална схема</h3><img src="https://upload.wikimedia.org/wikipedia/commons/c/c0/MMC4001.jpg" alt="Интегрална схема MMC4001 в корпус с два реда изводи" style="height:200px;width:100%;object-fit:contain"><figcaption>В корпуса има чип с много свързани електронни елементи. Виждат се двата реда изводи.<br>Mister rf · <a href="https://commons.wikimedia.org/wiki/File:MMC4001.jpg">Commons</a> · <a href="https://creativecommons.org/licenses/by-sa/4.0/">CC BY-SA 4.0</a></figcaption></figure></div><p><small>Снимките показват примери за трите вида компоненти и не са в еднакъв мащаб.</small></p>'''+timeline+'''<p>Следващата голяма стъпка е замяната на лампите с <strong>транзистори</strong>. Те са полупроводникови елементи, които могат да управляват електрически сигнали и да действат като превключватели. По-малки са и обикновено изискват по-малко енергия. Това позволява по-компактни и по-надеждни компютри, макар че охлаждането продължава да е необходимо.</p><p>Учебникът свързва второто поколение с 1959–1963 г. Разширява се използването на магнитни дискове, развиват се програмните езици и средствата за обмен на данни. Посоченият диапазон от около 200 000 до 1 000 000 операции в секунда е исторически ориентир, който зависи от конкретната машина.</p><p>Но дори малките транзистори трябва да се свържат. Когато са много отделни компоненти, връзките заемат място и усложняват производството. <strong>Интегралната схема</strong> обединява множество електронни елементи върху обща полупроводникова подложка. Така намаляват размерите и разстоянията между тях.</p><p>Третото поколение, приблизително през 60-те години до началото на 70-те, използва интегрални схеми. Развива се работата с няколко програми, както и операционният и приложният софтуер; през 1969 г. започва историята на Unix. Появяват се нови начини за взаимодействие, включително мишката. Скоростите на отделни системи достигат милиони операции в секунда, но няма една обща скорост за поколението. Важна е причинната връзка: интеграцията позволява по-сложни системи в по-малък обем.</p>''')
choice('gen-transistor-check','Защо транзисторите и интегралните схеми променят компютрите?',['Транзисторите позволяват по-малки електронни устройства.','Интегралната схема обединява много елементи върху обща подложка.','Транзисторният компютър никога не отделя топлина.','Интеграцията намалява нуждата от много отделни външни връзки.','Всички компютри от едно поколение имат еднаква скорост.','Интегрална схема означава програма за рисуване.'],[0,1,3],'Промените са в електронните компоненти и връзките им. Намалените размери и енергопотребление не означават липса на топлина.')
info('gen-micro','Микропроцесорът и персоналният компютър',photo('https://upload.wikimedia.org/wikipedia/commons/3/30/Intel_4004_open.jpg','Intel 4004 от 1971 г. с отворен корпус: в средата се вижда силициевият чип, а тънките проводници го свързват с изводите.','Science Museum · <a href="https://commons.wikimedia.org/wiki/File:Intel_4004_open.jpg">Commons</a> · <a href="https://creativecommons.org/licenses/by/4.0/">CC BY 4.0</a>')+'''<p>Представи си следващата стъпка: вместо процесорът да е разпределен между много платки, основните му функции се събират в интегрална схема. Това е <strong>микропроцесорът</strong>. Развитието му в началото на 70-те години е важен ориентир за четвъртото поколение.</p><p>Учебникът поставя началото му след 1971 г. Схемите с висока степен на интеграция позволяват все повече транзистори да се разполагат върху малка силициева подложка. Усъвършенстват се както процесорите, така и паметта. По-ниската цена и по-малките размери подпомагат появата на персонални компютри за училища, офиси и домове.</p><p>„Персонален“ не означава, че машината може да изпълнява само една задача. Означава, че е предназначена за непосредствена работа на отделен потребител. Същата система може да обработва текст, да изчислява таблица и да изпълнява други програми.</p><p>Сравнението със старите машини показва огромен растеж на паметта и изчислителните възможности. Но твърдение като „милион пъти по-добър“ има смисъл само ако уточним показателя и сравняваните модели. Капацитетът, скоростта, размерите и разходът на енергия са различни характеристики. Снимката показва корпус на конкретен процесор, а не целия компютър: нужни са още памет, платка, захранване и други устройства.</p>''')
choice('gen-micro-check','Кои изводи за четвъртото поколение са правилни?',['Микропроцесорът реализира основни процесорни функции в интегрална схема.','Един CPU сам по себе си е завършен компютър за работа.','Високата интеграция подпомага намаляването на размерите.','Персонален компютър означава компютър с единствена разрешена програма.','За сравнение във времена и поколения трябва да уточним показателя.','Всички характеристики се увеличават с точно еднакъв множител.'],[0,2,4],'Микропроцесорът е част от системата. Интеграцията подпомага миниатюризацията, а историческите сравнения изискват конкретен показател.')
info('configuration','Компютърна конфигурация: частите трябва да работят заедно',spec+'''<p>Когато избираме компютър, не избираме само процесор. <strong>Компютърната конфигурация</strong> включва хардуера и програмното осигуряване, които ще работят заедно. Подходящата комбинация зависи от задачите: писането на документ и сложното триизмерно моделиране имат различни изисквания.</p><p><strong>Дънната платка</strong> свързва компонентите и определя съвместимите процесори и памети. CPU изпълнява инструкциите, RAM осигурява работно пространство, а SSD или твърдият диск пази файловете. Графичната система обработва изображението; тя може да е вградена или отделна видеокарта. Звуковият и мрежовият контролер осигуряват съответно звук и комуникация и също могат да са вградени. Захранването подава необходимата електрическа енергия.</p><p>Към конфигурацията принадлежат и периферните устройства: монитор, клавиатура, мишка, принтер. Удобният екран има значение за продължителната работа, дори да не ускорява изчисленията. Операционната система и приложните програми трябва да са съвместими с хардуера и да позволяват нужните задачи.</p><p>Разгледай сравнението. При еднакви други условия 16 GB RAM могат да помогнат, когато отворените програми не се побират удобно в 8 GB. За малък документ разликата може да не се усеща. Не купуваме всяка част отделно по най-голямата цифра — търсим подходяща и съвместима система.</p>''')
choice('configuration-check','Кои решения показват разумен избор на конфигурация?',['Проверявам дали процесорът и RAM са съвместими с дънната платка.','Избирам само най-високата честота и пренебрегвам останалото.','Съобразявам графичната система с работата с 3D модели.','Приемам, че всички звукови и мрежови контролери са отделни карти.','Проверявам дали необходимите програми работят с избраната система.','Смятам, че двойно повече RAM винаги удвоява скоростта.'],[0,2,4],'Съвместимостта и нуждите на задачата са водещи. Контролерите може да са вградени, а повече RAM помага само когато има нужда от капацитета.')
info('inspect','Проучи учебния компютър',photo(RAM,'В Windows ще потърсиш общия обем на инсталираната RAM, а не броя видими чипове на модул.',ramcredit)+'''<p>Сега ще свържеш понятията с компютъра, на който работиш. Не е необходимо да отваряш корпуса. В Windows основните характеристики могат да се видят през настройките на системата. Имената на някои менюта зависят от версията и езика.</p><ol><li>Натисни клавиша Windows, въведи <strong>„За вашия компютър“</strong> или <strong>About your PC</strong> и отвори съответния резултат. Друг път е Настройки → Система → Относно.</li><li>В „Спецификации на устройството“ намери <strong>Процесор</strong> и <strong>Инсталирана RAM</strong>. Запиши модела и обема точно както са показани.</li><li>Намери „Тип система“. Той може да показва 64-битова операционна система и типа на процесора. Това не е капацитетът на паметта.</li><li>В „Спецификации на Windows“ виж изданието на операционната система.</li></ol><p>Използвай наученото, за да разтълкуваш полетата. Например „16 GB RAM“ описва обема на работната памет; моделът на CPU помага да потърсим неговите характеристики. Не е нужно да преписваш идентификатори на устройството или продуктов ключ. Ако училищните настройки ограничават достъпа, работи с учебния пример: CPU с четири ядра, 8 GB RAM и 256 GB SSD, и ясно го обозначи като пример.</p>''')
opened('inspect-check','Опиши намерената конфигурация','Посочи модела на процесора, обема RAM и изданието на Windows, които намери, или обозначи, че използваш учебния пример. Обясни със свои думи какво означава обемът RAM. Дай пример за своя учебна задача и кои компоненти са важни за нея.','Моят компютър има процесор Intel Core i5-13420H, 16 GB RAM и операционна система Windows 11 Education. RAM е работната памет, в която се съхраняват използваните в момента програми и данни. Например, когато подготвям презентация със снимки, процесорът изпълнява инструкциите на програмата, а в RAM се държат текущата презентация и изображенията, с които работя. Ако отворя едновременно презентацията и много страници в браузъра, е необходима повече работна памет.')
info('bulgaria','От „Витоша“ до българското производство',photo(ENIAC,'За сравнение: ранна електронна машина в САЩ. Българската „Витоша“ е друга машина, създадена по-късно. U. S. Army Photo.')+'''<p>Развитието на компютърните технологии достига и България чрез нуждата от научни и инженерни изчисления. През 1961 г. се създава изчислителен център под ръководството на Любомир Илиев. В началото на 60-те години започва работата по първата българска цифрова електронноизчислителна машина — <strong>„Витоша“</strong>, която работи през 1963 г.</p><p>За тогавашните специалисти целта не е домашен компютър с графичен екран, а машина, която извършва нужни пресмятания. Изграждането ѝ създава и опит: инженери трябва да проектират електронни устройства, а математици и програмисти — да организират решаването на задачи.</p><p>През 1965 г. е демонстриран електронният калкулатор <strong>ЕЛКА 6521</strong>. Калкулаторът е насочен към пресмятания и не бива да го смесваме с универсален персонален компютър. Разработките показват как знанията могат да се превърнат в устройства за практическа употреба.</p><p>През 1966 г. е създаден Централният институт по изчислителна техника. Заводът за изчислителна техника в София произвежда ЗИТ-151. През 70-те години се развиват производството на запаметяващи устройства с магнитни ленти и дискове, процесори и миникомпютри като ИЗОТ 310. Това вече е работа по цяла система от технологии — изчисляване, съхранение, производство и обслужване, а не само по един отделен уред.</p>''')
choice('bulgaria-check','Кои твърдения правилно описват разгледаното развитие?',['„Витоша“ е българска електронноизчислителна машина.','ЕЛКА 6521 е съвременна операционна система.','Производството включва и устройства за съхранение, не само процесори.','Снимката на ENIAC показва самата „Витоша“.','Калкулаторът ЕЛКА е предназначен за пресмятания.','Българската компютърна техника започва единствено с домашните лаптопи.'],[0,2,4],'„Витоша“ е изчислителна машина, ЕЛКА — калкулатор. Развитието обхваща много компоненти и производствени дейности; снимката е сравнителен пример на ENIAC.')
info('pravetz','ИМКО и „Правец“: компютърът стига до отделния човек',photo(PRAV,'„Правец 82“: виж отделния монитор и клавиатурата в корпуса на компютъра.',pravcredit)+'''<p>В края на 70-те години започва разработването на български персонални компютри. През 1980 г. се появяват първите ИМКО — „Индивидуален микрокомпютър“. Името изразява промяна в начина на работа: човек може непосредствено да използва собствено работно място с клавиатура и екран.</p><p>През 1982 г. ИМКО-2 получава името <strong>„Правец 82“</strong> и поставя началото на познатата серия. „Правец 82“ е съвместим с Apple II, а не с Apple I. Това е важно разграничение между различни модели. Съвместимостта позволява използване на подходящ софтуер от същата компютърна платформа.</p><p>Разгледай снимката: клавиатурата е част от основния корпус, а мониторът стои отделно. В сравнение с компютърна зала това е работно място за един човек. В училище подобна машина може да се използва за обучение по програмиране, упражнения и работа с учебни програми.</p><p>Как да сравним стар и днешен персонален компютър? Избираме едни и същи показатели: процесор, памет, съхранение, периферия и задачи. Илюстративно 48 KiB RAM са 49 152 байта, а 8 GiB са 8 589 934 592 байта — около 175 хиляди пъти повече памет. Това не означава същото увеличение на скоростта. Днешните програми, изображения и операционни системи също изискват много повече ресурси. Развитието се вижда най-добре чрез възможните задачи, а не само чрез голямо число.</p>''')
choice('pravetz-check','Какво показва сравнението между старите персонални компютри и днешните?',['ИМКО означава „Индивидуален микрокомпютър“.','„Правец 82“ е свързан със съвместимост с Apple II.','175 хиляди пъти повече RAM доказва точно толкова пъти по-бързо изпълнение.','Сравняването изисква еднакви показатели и ясни единици.','Apple I и Apple II са едно и също означение.','Персоналният компютър задължително има екран, вграден в корпуса.'],[0,1,3],'Сравняваме отделно капацитет, производителност и предназначение. „Правец 82“ е Apple II-съвместим, а персонален не означава непременно всичко в един корпус.')
info('summary','Най-важното от урока',arch+'''<ol><li><strong>Съхранявана програма:</strong> в модела на Фон Нойман паметта съдържа инструкции и данни; друга програма позволява друга задача.</li><li><strong>Процесор:</strong> управлението координира, АЛУ обработва, регистрите пазят непосредствено нужните стойности.</li><li><strong>Памет:</strong> RAM е работното пространство, кешът ускорява достъпа, а записаният файл остава на трайния носител.</li><li><strong>Развитие:</strong> лампи → транзистори → интегрални схеми и микропроцесори позволяват по-компактни системи; България участва с „Витоша“, ЕЛКА, ИЗОТ и „Правец“.</li><li><strong>Избор:</strong> конфигурацията трябва да е съвместима и подходяща за задачите. GHz, GB и GB/s измерват различни неща.</li></ol>''')
